describe('choosing an option', () => {
  it.each([
    ['ChipGroup', (onChange: (i: number) => void) => <ChipGroup testID="g" items={['A', 'B']} activeIndex={0} onChange={onChange} />],
    ['SegmentedControl', (onChange: (i: number) => void) => <SegmentedControl testID="g" options={['A', 'B']} activeIndex={0} onChange={onChange} />],
    ['TileGroup', (onChange: (i: number) => void) => <TileGroup testID="g" items={[{ label: 'A' }, { label: 'B' }]} activeIndex={0} onChange={onChange} columns={2} />],
  ])('%s reports the index that was pressed', (_name, build) => {
    const onChange = jest.fn();
    const m = mount(build(onChange));
    const presses = m.props((x) => typeof x.onPress === 'function');
    expect(presses.length).toBeGreaterThan(1);
    // press EVERY option: which tree node holds which index is the component's
    // business, and each option carries its own onChange(i)
    for (const p of presses) act(() => p.onPress());
    expect(onChange).toHaveBeenCalled();
    // nested pressables mean an index can fire more than once; what matters is
    // that BOTH options are reachable
    expect(new Set(onChange.mock.calls.map((c) => c[0]))).toEqual(new Set([0, 1]));
    m.unmount();
  });
});

describe('MonthCalendar interaction', () => {
  it('highlights on hover, clears it, and reports the day picked', () => {
    const onChange = jest.fn();
    const m = mount(<MonthCalendar value="2026-08-19" onChange={onChange} onCancel={jest.fn()} />);
    const hoverable = m.props((x) => typeof x.onHoverIn === 'function');
    expect(hoverable.length).toBeGreaterThan(0);
    for (const h of hoverable) {
      act(() => h.onHoverIn());
      if (typeof h.onHoverOut === 'function') act(() => h.onHoverOut());
    }
    // press every day cell: only the ones that ARE days report a date
    for (const p of m.props((x) => typeof x.onPress === 'function')) act(() => p.onPress());
    expect(onChange).toHaveBeenCalled();
    m.unmount();
  });
  it('DateField commits a chosen date and can be cancelled', () => {
    const onChange = jest.fn();
    const m = mount(<DateField testID="df" value="" onChange={onChange} />);
    act(() => m.props((x) => typeof x.onPress === 'function')[0]!.onPress());
    // the calendar inside the sheet reports through ITS onChange, which is the
    // handler that both commits the date and closes the sheet — reached from the
    // calendar's own prop rather than by pressing a day cell, because the sheet
    // unmounts the cell as it closes
    const calendars = m.props((x) => typeof x.onChange === 'function' && typeof x.onCancel === 'function');
    expect(calendars.length).toBeGreaterThan(0);
    act(() => calendars[0]!.onChange('2026-08-19'));
    expect(onChange).toHaveBeenCalledWith('2026-08-19');
    // and cancelling closes it without reporting anything
    const again = mount(<DateField testID="df" value="" onChange={jest.fn()} />);
    act(() => again.props((x) => typeof x.onPress === 'function')[0]!.onPress());
    for (const c of again.props((x) => typeof x.onCancel === 'function')) act(() => c.onCancel());
    again.unmount();
    m.unmount();
  });

  it('SliderCtl claims the gesture so a drag does not scroll the screen', () => {
    const m = mount(
      <SliderCtl testID="sl" progress={0.5} trackColor="#eee" fillColor="#4c8bf5" thumbColor="#fff" />,
    );
    const claims = m.props(
      (x) => typeof x.onStartShouldSetResponder === 'function' || typeof x.onMoveShouldSetResponder === 'function',
    );
    expect(claims.length).toBeGreaterThan(0);
    for (const c of claims) {
      if (typeof c.onStartShouldSetResponder === 'function') expect(c.onStartShouldSetResponder()).toBe(true);
      if (typeof c.onMoveShouldSetResponder === 'function') expect(c.onMoveShouldSetResponder()).toBe(true);
    }
    m.unmount();
  });
});

describe('SliderCtl dragging', () => {
  it('measures itself, then tracks a drag across the track', () => {
    const m = mount(<SliderCtl testID="sl" progress={0} trackColor="#eee" fillColor="#4c8bf5" thumbColor="#fff" />);
    const laid = m.props((x) => typeof x.onLayout === 'function');
    expect(laid.length).toBeGreaterThan(0);
    act(() => laid[0]!.onLayout({ nativeEvent: { layout: { width: 200, height: 8 } } }));
    // PanResponder reads touchHistory off the event, so a bare nativeEvent
    // crashes with "Cannot read properties of undefined (reading 'touchBank')"
    const bank = {
      touchActive: true,
      startPageX: 0, startPageY: 0, startTimeStamp: 0,
      currentPageX: 100, currentPageY: 0, currentTimeStamp: 1,
      previousPageX: 0, previousPageY: 0, previousTimeStamp: 0,
    };
    const touch = {
      touchHistory: {
        touchBank: [bank],
        numberActiveTouches: 1,
        indexOfSingleActiveTouch: 0,
        mostRecentTimeStamp: 1,
      },
    };
    const responders = m.props((x) => typeof x.onResponderGrant === 'function' || typeof x.onResponderMove === 'function');
    for (const r of responders) {
      if (typeof r.onResponderGrant === 'function') {
        act(() => r.onResponderGrant({ ...touch, nativeEvent: { locationX: 100 } }));
      }
      if (typeof r.onResponderMove === 'function') {
        act(() => r.onResponderMove({ ...touch, nativeEvent: { locationX: 180 } }));
      }
    }
    expect(m.json()).not.toBe('null');
    m.unmount();
  });
});

describe('chart colour parsing', () => {
  it('reads every hex form a design can use', () => {
    expect(tint('#abc', 0)).toContain('rgba(');
    expect(tint('#abcd', 0)).toContain('rgba(');
    expect(tint('#aabbcc', 0)).toContain('rgba(');
    expect(tint('#aabbccdd', 0)).toContain('rgba(');
  });
  it('returns an unreadable colour untouched rather than guessing', () => {
    expect(tint('#ab', 0.5)).toBe('#ab');
    expect(tint('#abcde', 0.5)).toBe('#abcde');
    expect(tint('teal', 0.5)).toBe('teal');
  });
  it('accepts a NUMERIC marker label', () => {
    expect(resolveChartProps({ marker: { index: 1, label: 42 } }).marker?.label).toBe('42');
    expect(resolveChartProps({ marker: { index: 1, label: { odd: true } } }).marker?.label).toBe('');
  });
  it('renders a donut where one segment has no value at all', () => {
    let tree!: renderer.ReactTestRenderer;
    act(() => {
      tree = renderer.create(
        <Chart chartType="donut" values={[0, 3, 0]} labels={['a', 'b', 'c']} width={200} height={160} />,
      );
    });
    expect(JSON.stringify(tree.toJSON())).not.toBe('null');
    act(() => tree.unmount());
  });
  it('renders a bar chart with a square (radius-free) bar', () => {
    let tree!: renderer.ReactTestRenderer;
    act(() => {
      tree = renderer.create(<Chart chartType="bar" values={[1, 2]} barRadius={0} width={200} height={100} />);
    });
    expect(JSON.stringify(tree.toJSON())).not.toBe('null');
    act(() => tree.unmount());
  });
});
